package dev.mando;
import org.bukkit.Bukkit;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.player.PlayerQuitEvent;import java.util.*;
public final class TpaManager implements Listener{public record Req(UUID from,UUID to,boolean here,long expires){}private final MandoPlugin plugin;private final Map<UUID,Req> in=new HashMap<>(),out=new HashMap<>();private final Set<UUID> off=new HashSet<>();public TpaManager(MandoPlugin p){plugin=p;}public boolean disabled(Player p){return off.contains(p.getUniqueId());}public boolean toggle(Player p){if(!off.add(p.getUniqueId()))off.remove(p.getUniqueId());return !off.contains(p.getUniqueId());}public String request(Player f,Player t,boolean here){if(f.equals(t))return "No puedes enviarte TPA a ti mismo.";if(disabled(t))return "Ese jugador no acepta TPA.";cancel(f);Req r=new Req(f.getUniqueId(),t.getUniqueId(),here,System.currentTimeMillis()+30000);in.put(r.to(),r);out.put(r.from(),r);Bukkit.getScheduler().runTaskLater(plugin,()->expire(r),600L);t.sendMessage("§6Mando §8» §f"+f.getName()+(here?" quiere que vayas hacia él.":" quiere ir hacia ti.")+" §a/tpaccept §7o §c/tpdeny");return "Solicitud enviada.";}public String accept(Player t){Req r=in.remove(t.getUniqueId());if(r==null||r.expires()<System.currentTimeMillis())return "No tienes TPA pendiente.";out.remove(r.from());Player f=Bukkit.getPlayer(r.from());if(f==null)return "El jugador se desconectó.";Player mover=r.here()?t:f,target=r.here()?f:t;mover.teleportAsync(target.getLocation());f.sendMessage("§6Mando §8» §aTPA aceptado.");return "TPA aceptado.";}public String deny(Player t){Req r=in.remove(t.getUniqueId());if(r==null)return "No tienes TPA pendiente.";out.remove(r.from());return "TPA rechazado.";}public String cancel(Player f){Req r=out.remove(f.getUniqueId());if(r==null)return "No tienes TPA saliente.";in.remove(r.to());return "TPA cancelado.";}private void expire(Req r){if(in.get(r.to())==r){in.remove(r.to());out.remove(r.from());}}@EventHandler public void quit(PlayerQuitEvent e){Req a=in.remove(e.getPlayer().getUniqueId());if(a!=null)out.remove(a.from());Req z=out.remove(e.getPlayer().getUniqueId());if(z!=null)in.remove(z.to());}}
